function tdzDemo(){try{print(n)}catch(n){print("caught:",n.constructor.name,n instanceof ReferenceError)}let n="now-initialized";print("after declaration:",n)}function blockTdz(){{try{print(n)}catch(n){print("inner block TDZ caught:",n.constructor.name)}let n="shadowed";print("inner val:",n,"val2:","inner-shadow")}print("outer val unchanged:","outer")}tdzDemo(),blockTdz();